// School Configuration
// Update these values to customize your school's branding

export const theme = {
  // School Information
  schoolName: 'AH Digital Academy',
  schoolTagline: 'Excellence in Education',
  schoolLogo: '/logo.png', // Replace with your logo file in public folder

  // Color Scheme
  colors: {
    primary: '#1E3A8A',      // Royal Blue - Trust, Professionalism
    secondary: '#F59E0B',    // Golden Amber - Excellence, Achievement
    accent: '#10B981',       // Emerald Green - Growth, Success
    background: '#F3F4F6',   // Light Gray
    text: '#1F2937',         // Dark Slate
    white: '#FFFFFF',
    success: '#22C55E',
    warning: '#F97316',
    danger: '#EF4444',
  },

  // UI Components
  card: {
    background: '#FFFFFF',
    shadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)',
    rounded: 'rounded-lg',
  },

  // Navigation
  sidebar: {
    background: '#1E3A8A',
    textColor: '#FFFFFF',
    activeBg: '#3B82F6',
    width: 'w-64',
  },

  // Buttons
  button: {
    primary: 'bg-blue-600 hover:bg-blue-700 text-white',
    secondary: 'bg-amber-500 hover:bg-amber-600 text-white',
    success: 'bg-green-500 hover:bg-green-600 text-white',
    danger: 'bg-red-500 hover:bg-red-600 text-white',
  },
}

export default theme
